-- Attendance is online-only in the MVP. Timestamps are generated by the server.
CREATE TABLE "attendance_records" (
    "id" UUID NOT NULL,
    "user_id" BIGINT NOT NULL,
    "store_id" BIGINT NOT NULL,
    "home_store_id_at_check_in" BIGINT NOT NULL,
    "is_support" BOOLEAN NOT NULL DEFAULT false,
    "check_in_device_id" UUID NOT NULL,
    "check_out_device_id" UUID,
    "check_in_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "check_out_at" TIMESTAMPTZ(3),
    "is_missed_checkout" BOOLEAN NOT NULL DEFAULT false,
    "is_manual_entry" BOOLEAN NOT NULL DEFAULT false,
    "received_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "attendance_records_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "attendance_records_user_id_check_out_at_idx"
    ON "attendance_records"("user_id", "check_out_at");
CREATE INDEX "attendance_records_store_id_check_in_at_idx"
    ON "attendance_records"("store_id", "check_in_at");
CREATE UNIQUE INDEX "attendance_records_one_open_per_user_idx"
    ON "attendance_records"("user_id") WHERE "check_out_at" IS NULL;

ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_user_id_fkey"
    FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_store_id_fkey"
    FOREIGN KEY ("store_id") REFERENCES "stores"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_home_store_id_at_check_in_fkey"
    FOREIGN KEY ("home_store_id_at_check_in") REFERENCES "stores"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_check_in_device_id_fkey"
    FOREIGN KEY ("check_in_device_id") REFERENCES "devices"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_check_out_device_id_fkey"
    FOREIGN KEY ("check_out_device_id") REFERENCES "devices"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_interval_check"
    CHECK ("check_out_at" IS NULL OR "check_out_at" >= "check_in_at");
ALTER TABLE "attendance_records"
    ADD CONSTRAINT "attendance_records_checkout_device_check"
    CHECK (("check_out_at" IS NULL) = ("check_out_device_id" IS NULL));
